from dataclasses import dataclass

@dataclass(frozen=True)
class Submission:
    learner: str
    quiz_id: str
    score: dict

    def to_dict(self):
        return {"learner": self.learner, "quiz_id": self.quiz_id, "score": self.score}

from flask import Blueprint, jsonify, request, session
from services.scoring import score_quiz
from models import Submission

api = Blueprint("quiz", __name__)

@api.post("/login")
def login():
    # Demonstration identity only; never use this as production authentication.
    name = (request.get_json(silent=True) or {}).get("name", "").strip()
    if not name:
        return jsonify(error="name required"), 400
    session["name"] = name
    return jsonify(name=name)

@api.post("/quizzes/<quiz_id>/submit")
def submit_quiz(quiz_id):
    if "name" not in session:
        return jsonify(error="sign in first"), 401
    answers = (request.get_json(silent=True) or {}).get("answers", {})
    if not isinstance(answers, dict):
        return jsonify(error="answers must be an object"), 400
    result = score_quiz(quiz_id, answers)
    if result is None:
        return jsonify(error="quiz not found"), 404
    submission = Submission(session["name"], quiz_id, result)
    return jsonify(submission.to_dict()), 201

@api.post("/logout")
def logout():
    session.clear()
    return jsonify(ok=True)

ANSWER_KEYS = {"python-basics": {"q1": "list", "q2": "def", "q3": "None"}}

def score_quiz(quiz_id, answers):
    key = ANSWER_KEYS.get(quiz_id)
    if key is None:
        return None
    correct = sum(answers.get(question) == expected for question, expected in key.items())
    return {"correct": correct, "total": len(key), "percentage": round(100 * correct / len(key), 1)}

from services.scoring import score_quiz

def test_full_score():
    result = score_quiz("python-basics", {"q1": "list", "q2": "def", "q3": "None"})
    assert result["percentage"] == 100.0

def test_missing_answers():
    assert score_quiz("python-basics", {})["correct"] == 0

def test_unknown_quiz():
    assert score_quiz("missing", {}) is None
